"""Mesh network coordination model — model for AI-Managed Global Freight Optimization.
Domain: transportation and mobility. Deterministic demonstration model (seeded).
"""
import random

class AIManagedGlobalFreightOptimizationSim:
    """Message routing across a mesh of nodes with link failures."""

    def __init__(self, n_nodes=16, seed=7):
        self.rng = random.Random(seed)
        self.n = n_nodes
        # ring + random shortcuts topology
        self.links = {i: {(i - 1) % n_nodes, (i + 1) % n_nodes} for i in range(n_nodes)}
        for _ in range(n_nodes):
            a, b = self.rng.randrange(n_nodes), self.rng.randrange(n_nodes)
            if a != b:
                self.links[a].add(b)
                self.links[b].add(a)

    def route(self, src, dst, fail_p=0.08):
        """Greedy geographic-ish routing with one retry on failure."""
        seen, node, hops = set(), src, 0
        while node != dst and hops < 3 * self.n:
            seen.add(node)
            nbrs = [x for x in self.links[node] if x not in seen]
            if not nbrs:
                return None
            nxt = min(nbrs, key=lambda x: abs(x - dst))
            if self.rng.random() < fail_p:
                seen.add(nxt)  # link failed; try another neighbor
                continue
            node = nxt
            hops += 1
        return hops if node == dst else None

    def trial(self, n_msgs=200):
        hops, lost = [], 0
        for _ in range(n_msgs):
            h = self.route(self.rng.randrange(self.n), self.rng.randrange(self.n))
            if h is None:
                lost += 1
            else:
                hops.append(h)
        return {"delivered_pct": round(100 * (1 - lost / n_msgs), 1),
                "avg_hops": round(sum(hops) / len(hops), 2) if hops else 0.0,
                "nodes": self.n}


if __name__ == "__main__":
    net = AIManagedGlobalFreightOptimizationSim(n_nodes=16, seed=7)
    r = net.trial(300)
    print("AI-Managed Global Freight Optimization mesh network model")
    print("delivered:", r["delivered_pct"], "% | avg hops:", r["avg_hops"])
